import { type Command, type HelpConfiguration } from 'commander';
/**
 * Commands that forward everything after their name to another program.
 *
 * `buy curl --json '{…}'` is curl's flag; `buy claude --resume` is claude's.
 * These are the only places a global flag after the subcommand is NOT buy's,
 * so they get no mirrors and a help note instead.
 */
export declare const PASSTHROUGH_COMMANDS: ReadonlySet<string>;
/**
 * Help configuration for every command: list the root flags under "Global
 * Options" so `buy whoami --help` shows them — once, since the mirrors below
 * are hidden.
 *
 * Minus `--version`. Commander lists every visible root option there, but the
 * version flag is handled by the root alone (`buy whoami -V` is a usage
 * error), and a help screen that offers a flag the command rejects is worse
 * than one that omits it. Applied per command by `main.ts`, because Commander
 * copies `_helpConfiguration` by value at `.command()` time.
 */
export declare const GLOBAL_OPTIONS_HELP: HelpConfiguration;
/**
 * Let a global flag be given AFTER the subcommand, for every command that is
 * not a passthrough.
 *
 * `buy whoami --json` was a usage error while `buy --json whoami` worked.
 * `enablePositionalOptions` is what makes `buy curl --json body` forward the
 * flag instead of eating it, and it also means the root stops parsing at the
 * first subcommand name — so a later `--json` reaches `whoami`, which did not
 * know it. The obvious repair, `passThroughOptions`, breaks a different flag
 * (see the comment on `enablePositionalOptions` in `main.ts`).
 *
 * So each leaf that is not a passthrough gets a HIDDEN copy of every root
 * option. Commander then parses `--json` wherever it is, and the actions —
 * which already read `cmd.optsWithGlobals()` — see it either way. Hidden, so
 * `--help` keeps listing each global once, under "Global Options".
 *
 * Copied from the root rather than restated here, in the root's order: the
 * `--json` / `--no-json` pair is a tri-state ONLY when the positive form is
 * defined first (a lone `--no-x` defaults to true), and a second list of the
 * globals would be a second place to keep in sync.
 *
 * `optsWithGlobals()` merges ancestors LAST ("globals overwrite locals" in
 * Commander 12), so with a flag on BOTH sides — `buy --no-json whoami --json`
 * — the root's value would win, while the argv scan in `main.ts` that seeds
 * the output mode takes the last occurrence. Same flags, two answers: a
 * usage error would come out as JSON and a runtime error as prose. So a
 * `preAction` hook here copies every mirrored value a leaf actually received
 * onto the root before any action or later hook reads it. The later flag
 * wins, everywhere, which is also what a repeated flag on one command does.
 * The root options carry no defaults, so a root key exists only when it was
 * passed; a leaf's value is copied only when the leaf was given the flag.
 *
 * A leaf that already defines the same long or short flag keeps its own; the
 * mirror is skipped rather than colliding. None do today (`fetch -X/-H/-d/-i`,
 * `verify --scope`), and this keeps the next one from throwing at startup.
 */
export declare function mirrorGlobalOptions(root: Command, passthrough: ReadonlySet<string>): void;
